using System;
using KingsCourt.Core;
using UnityEngine;
using UnityEngine.EventSystems;
using UnityEngine.UI;

namespace KingsCourt.UnityLayer
{
    /// <summary>
    /// One action card, drawn Uno-style. Built entirely in code: CardView.Create() makes the same card
    /// everywhere (hand, the trusted advisor's choices, the king's choices, the help panel).
    /// A Unity prefab of this is generated by the King's Court menu (Assets/Editor/CreatePrefabs.cs).
    /// </summary>
    public sealed class CardView : MonoBehaviour, IPointerClickHandler, IPointerEnterHandler, IPointerExitHandler
    {
        public const float Width = 196f;
        public const float Height = 280f;

        public ActionCard Card { get; private set; }
        public int Index;
        public event Action<CardView> Clicked;

        [SerializeField] private RectTransform visual;
        [SerializeField] private Image glow, border, body, header;
        [SerializeField] private Text title, category, effect;
        [SerializeField] private Image backPattern;
        private bool selected, playable = true, hover, faceDown;

        /// <summary>Optional: when set (from the CardView prefab), every card is an instance of it instead of being built in code.</summary>
        public static CardView Prefab;

        private float lift, scale = 1f;

        public static Color CategoryColor(CardCategory c)
        {
            switch (c)
            {
                case CardCategory.Execute: return new Color(.70f, .14f, .17f);
                case CardCategory.Reveal: return new Color(.16f, .40f, .72f);
                case CardCategory.Cards: return new Color(.18f, .55f, .33f);
                case CardCategory.NextRound: return new Color(.48f, .31f, .69f);
                default: return new Color(.78f, .46f, .10f);
            }
        }

        public static CardView Create(Transform parent, string name = "Card")
        {
            if (Prefab != null)
            {
                var inst = Instantiate(Prefab, parent, false);
                inst.name = name;
                return inst;
            }
            var root = UiKit.Rect(parent, name);
            root.sizeDelta = new Vector2(Width, Height);
            var hit = root.gameObject.AddComponent<Image>();      // invisible hit area so lifting does not flicker hover
            hit.color = new Color(0, 0, 0, 0);
            var cv = root.gameObject.AddComponent<CardView>();
            cv.Build();
            var le = root.gameObject.AddComponent<LayoutElement>();
            le.preferredWidth = Width;
            le.preferredHeight = Height;
            return cv;
        }

        public void Build()
        {
            visual = UiKit.Rect(transform, "Visual");
            visual.anchorMin = visual.anchorMax = new Vector2(.5f, 0f);
            visual.pivot = new Vector2(.5f, 0f);
            visual.sizeDelta = new Vector2(Width, Height);
            visual.anchoredPosition = Vector2.zero;

            var g = UiKit.Box(visual, "Glow", new Color(1f, .85f, .25f, 0f));
            UiKit.Stretch(g, -14, -14, -14, -14);
            glow = g.GetComponent<Image>();
            glow.raycastTarget = false;

            var b = UiKit.Box(visual, "Border", new Color(.1f, .09f, .09f));
            UiKit.Stretch(b);
            border = b.GetComponent<Image>();
            border.raycastTarget = false;

            var bd = UiKit.Box(visual, "Body", UiKit.Paper);
            UiKit.Stretch(bd, 6, 6, 6, 6);
            body = bd.GetComponent<Image>();
            body.raycastTarget = false;

            var h = UiKit.Box(bd, "Header", Color.gray);
            h.anchorMin = new Vector2(0, 1); h.anchorMax = new Vector2(1, 1); h.pivot = new Vector2(.5f, 1);
            h.sizeDelta = new Vector2(0, 58);
            header = h.GetComponent<Image>();
            header.raycastTarget = false;
            title = UiKit.Label(h, "", 21, Color.white, TextAnchor.MiddleCenter, FontStyle.Bold);
            UiKit.Stretch((RectTransform)title.transform, 4, 2, 4, 2);
            title.resizeTextForBestFit = true; title.resizeTextMinSize = 13; title.resizeTextMaxSize = 21;

            category = UiKit.Label(bd, "", 12, new Color(.35f, .3f, .3f), TextAnchor.MiddleCenter, FontStyle.Bold);
            var crt = (RectTransform)category.transform;
            crt.anchorMin = new Vector2(0, 1); crt.anchorMax = new Vector2(1, 1); crt.pivot = new Vector2(.5f, 1);
            crt.anchoredPosition = new Vector2(0, -62); crt.sizeDelta = new Vector2(0, 18);

            effect = UiKit.Label(bd, "", 15, UiKit.Ink, TextAnchor.UpperCenter);
            var ert = (RectTransform)effect.transform;
            UiKit.Stretch(ert, 10, 8, 10, 84);
            effect.resizeTextForBestFit = true; effect.resizeTextMinSize = 10; effect.resizeTextMaxSize = 17;

            var bp = UiKit.Box(visual, "BackPattern", new Color(.85f, .7f, .25f));
            bp.sizeDelta = new Vector2(62, 62);
            bp.anchorMin = bp.anchorMax = new Vector2(.5f, .5f);
            bp.localRotation = Quaternion.Euler(0, 0, 45);
            backPattern = bp.GetComponent<Image>();
            backPattern.raycastTarget = false;
            backPattern.enabled = false;
        }

        public void Set(ActionCard card, bool showBack = false)
        {
            Card = card;
            faceDown = showBack || card == null;
            body.color = faceDown ? new Color(.55f, .12f, .16f) : UiKit.Paper;
            header.gameObject.SetActive(!faceDown);
            category.gameObject.SetActive(!faceDown);
            effect.gameObject.SetActive(!faceDown);
            backPattern.enabled = faceDown;
            if (faceDown) return;
            var cat = CardInfo.Category(card.Effect);
            header.color = CategoryColor(cat);
            title.text = CardInfo.Title(card.Effect);
            category.text = cat.ToString().ToUpperInvariant();
            effect.text = card.Text;
        }

        public void SetState(bool isPlayable, bool isSelected)
        {
            playable = isPlayable;
            selected = isSelected;
            if (selected) transform.SetAsLastSibling();   // a selected card must draw over its neighbors too
            if (!Application.isPlaying) Apply(1f);   // edit mode (screenshots) has no Update loop
        }

        private void Update() { Apply(1f - Mathf.Exp(-16f * Time.unscaledDeltaTime)); }

        private void Apply(float k)
        {
            float targetLift = selected ? 52f : (hover && playable ? 22f : 0f);
            float targetScale = selected ? 1.10f : (hover && playable ? 1.07f : 1f);
            lift = Mathf.Lerp(lift, targetLift, k);
            scale = Mathf.Lerp(scale, targetScale, k);
            visual.anchoredPosition = new Vector2(0, lift);
            visual.localScale = new Vector3(scale, scale, 1f);

            // Selected: bright pulsing gold glow and gold frame. Others: normal frame, dimmed when not playable.
            float pulse = .65f + .35f * Mathf.Sin(Time.unscaledTime * 6f);
            glow.color = new Color(1f, .85f, .25f, selected ? pulse : 0f);
            border.color = selected ? UiKit.Gold : new Color(.1f, .09f, .09f);
            float dim = playable || selected ? 1f : .55f;
            body.color = faceDown ? new Color(.55f * dim, .12f * dim, .16f * dim) : new Color(UiKit.Paper.r * dim, UiKit.Paper.g * dim, UiKit.Paper.b * dim);
            if (!faceDown) header.color = Color.Lerp(Color.black, CategoryColor(CardInfo.Category(Card.Effect)), dim);
        }

        public void OnPointerClick(PointerEventData e) { if (Clicked != null) Clicked(this); }
        public void OnPointerEnter(PointerEventData e) { hover = true; transform.SetAsLastSibling(); }   // lifted card must draw over its neighbors, or its text hides behind them
        public void OnPointerExit(PointerEventData e) { hover = false; }
    }
}
